"""ArWen GPU tests that measure something the Apple Metal backend does not have.

tests/conftest.py skips them when GPUWM_BACKEND=metal, with the reason of their
class.  Every entry was classified from its failure on an Apple M3 Max
(2026-11-18) and, where it could fail for a Metal reason, run on the reference
RTX 5090 as well.  A test is listed only when its failure says nothing about
the correctness of the Metal port; everything else stays a real test.

``ENTRIES`` maps a test node id (or its unparametrised prefix) to a class.
"""
from __future__ import annotations

import os

CLASSES = {
    "ptx": "it compiles CUDA source to PTX/cubin through NVRTC, links with "
           "nvJitLink or patches PTX; Metal has no PTX (kernels are translated "
           "to MSL, gpuwm/metal/transpile.py)",
    "cuda_introspection": "it reads CUDA compiler/driver internals (local-memory "
                          "frames, registers, NVRTC builtin behaviour) that Metal "
                          "does not expose",
    "cuda_hash_pin": "it pins CUDA's output words or numbers measured on CUDA (SHA-256, the "
                     "words, published figures, or a measured distance from a WRF oracle), which encode ptxas's FMA "
                     "contraction under --fmad=true; Metal computes without contraction and is "
                     "closer to the WRF oracle where one exists (dycore: never farther)",
    "macos_reference": "its CPU reference runs on the Mac itself, linking Apple's "
                       "libm or NumPy for arm64 instead of glibc/x86 (Metal matches "
                       "the glibc words, e.g. logf(8841.5107) = 0x41116539)",
    "arwen_drift": "it fails on any backend in ArWen 3.0.3: the test and the code disagree "
                   "(the same failure on an RTX 5090, or an error raised by the test's own fixture)",
    "cuda_host_only": "it needs data, tools or an environment present only on the "
                      "CUDA/Linux machine (x86-64 Fortran builds, staged tables, "
                      "recorded baselines)",
    "cuda_contraction": "a negative control of nvrtc/ptxas FMA contraction: it pins what "
                        "contracting a*b+c does to a formula on CUDA; Metal compiles "
                        "without contraction, so the effect does not exist here",
    "cuda_streams": "it races two independent CUDA streams (a spin-wait gate released from "
                    "another stream); this backend runs every stream on one in-order Metal "
                    "queue, so the race it guards against cannot occur",
    "nan_encoding": "it compares the bit patterns of NaNs made by invalid operations, which "
                    "differ by hardware (Apple GPU 0xFFC00000 as x86, NVIDIA 0x7FFFFFFF, arm64 "
                    "CPUs 0x7FC00000) and between two formulations of the same arithmetic; "
                    "both words are NaN, finite results are unaffected",
    "cuda_tolerance": "a tolerance calibrated on CUDA's arithmetic (ptxas FMA contraction) over "
                      "a free-running integration; Metal's uncontracted arithmetic computes the "
                      "same scheme and lands just outside it (each case's margin in the README)",
    "native_libm": "it pins behaviour of CUDA's hardware powf -- its distance from glibc/WRF, "
                   "its word, or the levels where it departs from glibc's; Metal's powf follows "
                   "glibc's algorithm (0 of 1.89e6 differ where the rounding is certain)",
    "default_native_math": "a tolerance measured on CUDA for ArWen's default numerics, which "
                           "call the GPU's own float libm; with ARWEN_METAL_STRICT_GLIBC=1 "
                           "it runs here, and passes",
    "kf_default_tolerance": "ArWen 3.0.3's default KF-CuP numerics fail these word "
                            "counts on the RTX 5090 as well (e.g. rthcuten 1189 words "
                            "off on CUDA, 1255 on Metal); with ARWEN_METAL_STRICT_GLIBC=1 "
                            "they run here, and pass word-exact",
}

